    int tx = threadIdx.x, ty = threadIdx.y;

    // Each thread computes a 4x4 block of C
    float c[4][4] = {{0}};

    // Warp ID and lane ID
    int warpId = tx / 32;
    int laneId = tx % 32;

    // Loop over tiles
    for (int t = 0; t < N; t += TILE_SIZE) {
        // Vectorized loads for A using float4
        int a_row = by * TILE_SIZE + ty * 4;
        int a_col = t + tx * 4;

        if (a_row < N && a_col < N - 3) {
            float4 a4 = *reinterpret_cast<const float4*>(&A[a_row * N + a_col]);
            As[ty * 4][tx * 4] = a4.x;
            As[ty * 4 + 1][tx * 4] = a4.y;
            As[ty * 4 + 2][tx * 4] = a4.z;
            As[ty * 4 + 3][tx * 4] = a4.w;
        } else {
            #pragma unroll
            for (int i = 0; i < 4; i++) {
                int row = a_row + i;
                int col = a_col;
                As[ty * 4 + i][tx * 4] = (row < N && col < N) ? A[row * N + col] : 0.0f;
            }
