        __syncthreads();

        // Compute partial sums with loop unrolling
        #pragma unroll 8
        for (int k = 0; k < TILE_SIZE; k++) {
            float a_reg[4];
            float b_reg[4];

            // Load values into registers
            #pragma unroll
            for (int i = 0; i < 4; i++) {
